/* From Uiverse.io by r7chardgh - Tags: button, hover, stars */
.__UIV_SCOPE__ .stars {
  position: absolute;
  opacity: 0;
  top: -.3em;
  right: -.3em;
  height: 100%;
  transition: transform 300ms,opacity 150ms;
}

.__UIV_SCOPE__ .stars :nth-child(n) {
  fill: #999;
}

.__UIV_SCOPE__ .button {
  position: relative;
  cursor: pointer;
  padding: 1em 2em;
  border: 0;
  border-radius: .5em;
  font-weight: bolder;
  transition: transform 150ms, box-shadow 150ms;
  box-shadow: 0 0 #999;
  background-color: #f1f1f1;
  color: #333;
}

.__UIV_SCOPE__ .button:hover {
  transform: translate(.3em,-.3em);
  box-shadow: -.3em .3em #999;
}

.__UIV_SCOPE__ .button:hover > .stars {
  opacity: 1;
  transform: translate(.2em,-.2em);
}

.__UIV_SCOPE__ .button:active > .stars :nth-child(n) {
  fill: #ccc;
}
